SELECT rep.id, rep.department_id, dep.name AS department_name, rep.product_id, pro.name AS product_name, pro.unit_price AS product_unit_price, rep.current_quantity, rep.order_quantity_total, rep.order_date_latest, rep.create_time, rep.update_time, rep.create_by, rep.update_by FROM biz_repository rep left join sys_dept dep on rep.department_id = dep.id left join biz_products pro on rep.product_id = pro.id
WHERE rep.department_id IN
#{item}
